def parse_coverage(data, call):
    """The project's own coverage file: Cobertura XML when it starts with '<', else LCOV."""
    if data.lstrip()[:1] == b"<":
        return {**parse_cobertura(data, call), "format": "cobertura"}
    return {**parse_lcov(data, call), "format": "lcov"}


